<script>
(function () {
  'use strict';

  /* ── Commands data ──────────────────────────────────── */
  const COMMANDS = [
    { id:'go-dash',    section:'Navigation', label:'Dashboard',         desc:'Your main overview',         icon:'home',     kbd:['G','D'], href:'#' },
    { id:'go-proj',    section:'Navigation', label:'Projects',          desc:'Browse all projects',         icon:'folder',   kbd:['G','P'], href:'#' },
    { id:'go-team',    section:'Navigation', label:'Team',              desc:'Manage team members',         icon:'users',    kbd:['G','T'], href:'#' },
    { id:'go-set',     section:'Navigation', label:'Settings',          desc:'Preferences & account',       icon:'settings', kbd:['G','S'], href:'#' },
    { id:'new-proj',   section:'Actions',    label:'New project',       desc:'Create a blank project',      icon:'plus',     kbd:['N','P'], href:'#' },
    { id:'invite',     section:'Actions',    label:'Invite member',     desc:'Send a team invitation',      icon:'user-plus',kbd:['I','M'], href:'#' },
    { id:'theme-cmd',  section:'Preferences',label:'Toggle theme',      desc:'Switch light / dark mode',    icon:'sun',      kbd:null,      action:'toggle-theme' },
    { id:'docs',       section:'Resources',  label:'Documentation',     desc:'Open the developer docs',     icon:'book',     kbd:null,      href:'#' },
    { id:'shortcuts',  section:'Resources',  label:'Keyboard shortcuts',desc:'View all shortcuts',          icon:'keyboard', kbd:['?'],     href:'#' },
  ];

  /* ── Icons (currentColor only) ──────────────────────── */
  function iconSVG(name) {
    const p = {
      home:`<path d="M2 8L8 3l6 5" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
            <path d="M4 8v5a1 1 0 001 1h2v-3h2v3h2a1 1 0 001-1V8" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>`,
      folder:`<path d="M2 5a1 1 0 011-1h3l1.5 2H13a1 1 0 011 1v6a1 1 0 01-1 1H3a1 1 0 01-1-1V5z" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round"/>`,
      users:`<circle cx="6" cy="5" r="2.5" stroke="currentColor" stroke-width="1.5"/>
             <path d="M1 13.5c0-2.5 2.2-4 5-4s5 1.5 5 4" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/>
             <path d="M11 7c1.4 0 2.5 1 2.5 2.3V13" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/>`,
      settings:`<circle cx="8" cy="8" r="2" stroke="currentColor" stroke-width="1.5"/>
                <path d="M13.4 8c0-.3 0-.7-.1-1l1.5-1.2-1.5-2.6-1.8.7c-.5-.4-1.1-.7-1.7-.9L9.5 1h-3l-.3 2c-.6.2-1.2.5-1.7.9L2.7 3.2 1.2 5.8l1.5 1.2C2.6 7.3 2.6 7.7 2.6 8s0 .7.1 1L1.2 10.2l1.5 2.6 1.8-.7c.5.4 1.1.7 1.7.9l.3 2h3l.3-2c.6-.2 1.2-.5 1.7-.9l1.8.7 1.5-2.6L13.5 9c.1-.3.1-.7-.1-1z" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round"/>`,
      plus:`<path d="M8 2v12M2 8h12" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/>`,
      'user-plus':`<circle cx="6" cy="5" r="2.5" stroke="currentColor" stroke-width="1.5"/>
                   <path d="M1 13.5c0-2.5 2.2-4 5-4" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/>
                   <path d="M11 10v5M8.5 12.5h5" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/>`,
      sun:`<circle cx="8" cy="8" r="3" stroke="currentColor" stroke-width="1.5"/>
           <path d="M8 1v1.5M8 13.5V15M1 8h1.5M13.5 8H15M3.05 3.05l1.06 1.06M11.89 11.89l1.06 1.06M3.05 12.95l1.06-1.06M11.89 4.11l1.06-1.06" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/>`,
      book:`<path d="M3 2h9a1 1 0 011 1v11H4a1 1 0 00-1 1V2z" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round"/>
            <path d="M3 15a1 1 0 001 1h9V4" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round"/>
            <path d="M6 6h4M6 9h4" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/>`,
      keyboard:`<rect x="2" y="4" width="12" height="8" rx="1.5" stroke="currentColor" stroke-width="1.5"/>
                <path d="M5 7h1M9 7h1M7 7h1M5 9.5h5" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/>`,
    };
    return `<svg width="14" height="14" viewBox="0 0 16 16" fill="none" aria-hidden="true">${p[name]??''}</svg>`;
  }

  /* ── State ──────────────────────────────────────────── */
  let isOpen = false, query = '', selectedIdx = -1, filtered = [];

  /* ── DOM refs ───────────────────────────────────────── */
  const backdrop   = document.getElementById('cmd-backdrop');
  const dialog     = document.getElementById('cmd-dialog');
  const input      = document.getElementById('cmd-input');
  const resultsEl  = document.getElementById('cmd-results');
  const emptyEl    = document.getElementById('cmd-empty');
  const emptyQuery = document.getElementById('cmd-empty-query');
  const resetBtn   = document.getElementById('cmd-reset-btn');
  const clearBtn   = document.getElementById('cmd-clear-btn');
  const countHint  = document.getElementById('cmd-count-hint');
  const openBtn    = document.getElementById('cmd-open-btn');

  /* ── Open / Close ───────────────────────────────────── */
  function openPalette() {
    if (isOpen) return;
    isOpen = true;
    dialog.showModal();
    backdrop.classList.add('is-open');
    backdrop.setAttribute('aria-hidden', 'false');
    input.value = '';
    renderResults('');
    input.focus();
  }

  function closePalette() {
    if (!isOpen) return;
    isOpen = false;
    backdrop.classList.remove('is-open');
    backdrop.setAttribute('aria-hidden', 'true');
    const done = () => { if (!isOpen) dialog.close(); dialog.removeEventListener('transitionend', done); };
    dialog.addEventListener('transitionend', done);
    openBtn.focus();
  }

  /* ── Filter + highlight ─────────────────────────────── */
  function esc(s) {
    return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  }
  function hi(text, q) {
    if (!q.trim()) return esc(text);
    const e = esc(text), lq = esc(q).toLowerCase(), lt = e.toLowerCase();
    const i = lt.indexOf(lq);
    if (i < 0) return e;
    return e.slice(0,i) + `<mark class="cmd-match">${e.slice(i, i+lq.length)}</mark>` + e.slice(i+lq.length);
  }
  function filter(q) {
    if (!q.trim()) return COMMANDS;
    const lq = q.toLowerCase();
    return COMMANDS.filter(c =>
      c.label.toLowerCase().includes(lq) ||
      c.desc.toLowerCase().includes(lq) ||
      c.section.toLowerCase().includes(lq)
    );
  }

  /* ── Render ─────────────────────────────────────────── */
  function renderResults(q) {
    query = q;
    filtered = filter(q);
    selectedIdx = filtered.length > 0 ? 0 : -1;
    resultsEl.innerHTML = '';

    if (!filtered.length) {
      emptyEl.classList.add('is-visible');
      emptyQuery.textContent = q;
      countHint.textContent  = '';
      input.setAttribute('aria-activedescendant', '');
      return;
    }
    emptyEl.classList.remove('is-visible');

    // Group by section
    const sections = {};
    filtered.forEach((c,i) => { (sections[c.section] = sections[c.section]||[]).push({c,i}); });

    Object.entries(sections).forEach(([name, items]) => {
      const grp = document.createElement('div');
      grp.setAttribute('role','group'); grp.setAttribute('aria-label', name);
      grp.innerHTML = `<div class="cmd-section"><span class="cmd-section__label">${esc(name)}</span></div>`;

      items.forEach(({c,i}) => {
        const el = document.createElement('div');
        el.className = 'cmd-item';
        el.id = `cmd-item-${c.id}`;
        el.setAttribute('role','option');
        el.setAttribute('aria-selected','false');
        el.setAttribute('data-idx', i);
        el.setAttribute('tabindex','-1');

        const kbdHtml = c.kbd
          ? `<span class="cmd-item__kbd" aria-label="Shortcut: ${c.kbd.join(' ')}">${c.kbd.map(k=>`<kbd>${esc(k)}</kbd>`).join('')}</span>`
          : '';

        el.innerHTML = `
          <span class="cmd-item__icon" aria-hidden="true">${iconSVG(c.icon)}</span>
          <span class="cmd-item__text">
            <span class="cmd-item__label">${hi(c.label,q)}</span>
            <span class="cmd-item__desc">${hi(c.desc,q)}</span>
          </span>${kbdHtml}`;

        el.addEventListener('click',  () => activate(i));
        el.addEventListener('mousemove', () => setSelected(i));
        grp.appendChild(el);
      });
      resultsEl.appendChild(grp);
    });

    countHint.textContent = `${filtered.length} result${filtered.length!==1?'s':''}`;
    setSelected(0);
  }

  /* ── Selection ──────────────────────────────────────── */
  function setSelected(idx) {
    if (idx < 0 || idx >= filtered.length) return;
    selectedIdx = idx;
    resultsEl.querySelectorAll('.cmd-item').forEach((el,i) => {
      const on = i === idx;
      el.setAttribute('data-selected', on ? 'true' : 'false');
      el.setAttribute('aria-selected', on ? 'true' : 'false');
      if (on) { input.setAttribute('aria-activedescendant', el.id); el.scrollIntoView({block:'nearest'}); }
    });
  }

  function activate(idx) {
    const item = filtered[idx];
    if (!item) return;
    if (item.action === 'toggle-theme') toggleTheme();
    closePalette();
  }

  /* ── Keyboard ───────────────────────────────────────── */
  document.addEventListener('keydown', e => {
    if ((e.ctrlKey || e.metaKey) && e.key === 'k') {
      e.preventDefault();
      isOpen ? closePalette() : openPalette();
      return;
    }
    if (!isOpen) return;
    switch (e.key) {
      case 'Escape':    e.preventDefault(); closePalette(); break;
      case 'ArrowDown': e.preventDefault();
        if (filtered.length) setSelected((selectedIdx + 1) % filtered.length); break;
      case 'ArrowUp':   e.preventDefault();
        if (filtered.length) setSelected((selectedIdx - 1 + filtered.length) % filtered.length); break;
      case 'Enter':     e.preventDefault();
        if (selectedIdx >= 0) activate(selectedIdx); break;
      case 'Tab':       e.preventDefault(); break;
    }
  });

  /* ── Theme toggle ───────────────────────────────────── */
  function toggleTheme() {
    const html  = document.documentElement;
    const isDark = html.getAttribute('data-theme') === 'dark';
    html.setAttribute('data-theme', isDark ? 'light' : 'dark');
    document.getElementById('icon-sun').style.display  = isDark ? '' : 'none';
    document.getElementById('icon-moon').style.display = isDark ? 'none' : '';
  }

  /* ── Active nav pill ────────────────────────────────── */
  function updatePill() {
    const nav    = document.querySelector('.navbar__nav');
    const pill   = document.querySelector('.navbar__pill');
    const active = nav.querySelector('[aria-current="page"]');
    if (!active || !pill) return;
    const nr = nav.getBoundingClientRect(), ar = active.getBoundingClientRect();
    pill.style.left  = `${ar.left - nr.left}px`;
    pill.style.width = `${ar.width}px`;
  }

  /* ── Wire events ────────────────────────────────────── */
  openBtn.addEventListener('click', openPalette);
  backdrop.addEventListener('click', e => { if (e.target === backdrop) closePalette(); });
  input.addEventListener('input', () => renderResults(input.value));
  clearBtn.addEventListener('click', () => { input.value = ''; renderResults(''); input.focus(); });
  resetBtn.addEventListener('click', () => { input.value = ''; renderResults(''); input.focus(); });
  document.getElementById('theme-toggle').addEventListener('click', toggleTheme);

  document.getElementById('nav-hamburger').addEventListener('click', () => {
    const nav  = document.getElementById('main-nav');
    const btn  = document.getElementById('nav-hamburger');
    const open = nav.classList.toggle('is-open');
    btn.setAttribute('aria-expanded', open);
    document.getElementById('icon-menu').style.display       = open ? 'none' : '';
    document.getElementById('icon-close-menu').style.display = open ? '' : 'none';
  });

  document.querySelectorAll('.navbar__link').forEach(link => {
    link.addEventListener('click', e => {
      e.preventDefault();
      document.querySelectorAll('.navbar__link').forEach(l => l.removeAttribute('aria-current'));
      link.setAttribute('aria-current', 'page');
      updatePill();
      const nav = document.getElementById('main-nav');
      if (nav.classList.contains('is-open')) {
        nav.classList.remove('is-open');
        document.getElementById('nav-hamburger').setAttribute('aria-expanded','false');
        document.getElementById('icon-menu').style.display       = '';
        document.getElementById('icon-close-menu').style.display = 'none';
      }
    });
  });

  updatePill();
  window.addEventListener('resize', updatePill);

}());
</script>
